"mildly":{a:[{tr:"z. hafifçe, az miktarda",ex:"Most participants were only mildly affected by the treatment.",exTr:"Katılımcıların çoğu tedaviden yalnızca hafifçe etkilendi.",yz:4,exs:[{"ex":"The audience was mildly surprised by the result, but the discussion became more animated when the presenter explained how the original prediction had been made.","exTr":"Dinleyiciler sonuca hafifçe şaşırdı; ancak sunucu ilk tahminin nasıl yapıldığını açıklayınca tartışma daha canlı hâle geldi."}]},{tr:"z. yumuşak veya ılımlı biçimde",ex:"The chair responded mildly despite the harsh criticism.",exTr:"Başkan sert eleştiriye rağmen yumuşak bir tavırla karşılık verdi.",yz:2}],kl:[{en:"mildly surprised",tr:"hafifçe şaşırmış"},{en:"mildly critical",tr:"hafif ölçüde eleştirel"}]},
